    p3_filler = "Gió sớm mai thổi qua tán lá bàng đỏ thắm, mang theo hương thơm ngát của hoa sữa muộn và hương cà phê thơm nồng nơi đầu ngõ. Cuộc sống đời thường cứ thế êm ả trôi đi như một dòng sông hiền hòa không ngừng chảy. Đi qua những thăng trầm được mất, cay đắng ngọt bùi của kiếp nhân sinh, điều đọng lại sâu sắc nhất trong tim mỗi con người vẫn là tình mẫu tử thiêng liêng, tình người mộc mạc và sự bình yên trong tâm hồn. Hãy luôn yêu thương khi còn có thể, bởi vì thời gian trôi qua không bao giờ trở lại, và gia đình luôn là bến đỗ bình yên nhất che chở cho ta trước mọi bão giông cuộc đời."

    p3_full_text = "\n\n".join(p3_chunks)
    p3_full_text += "\n\n" + "\n\n".join(p3_expansions)
    p3_full_text += "\n\n" + "\n\n".join(p3_expansions_2)
